/** Render-producer-local diagnostics. Nested CPU wall times must not be added to pass totals. */
public final class Counters {
    public enum Key {RANGE_ALLOCATIONS,RANGE_ALLOC_BYTES,RANGE_ALLOC_NS,RANGE_BIND_NS,RANGE_VISITS,RANGE_SKIPS,RANGE_DIRTY,RANGE_UNKNOWN,RANGE_COPIES_ALL,RANGE_BYTES_ALL,LOCATIONS_HITS,LOCATIONS_MISSES,LOCATION_CALLS,LOCATION_NS,POINTER_UPDATES,DIVISOR_UPDATES,PROGRAM_QUERIES,BATCHES,MIRROR_HITS,MIRROR_BYTES,MIRROR_EVICTIONS,SCRATCH_ALLOCATIONS,SCRATCH_BYTES,SAMPLER_BINDS,SAMPLER_INVALIDATIONS,PACK_UPLOADS,PACK_BYTES,PACK_NS,TEX_BUFFER_REQUESTS,TEX_BUFFER_BINDS,TEX_BUFFER_BIND_SKIPS,TEX_BUFFER_NATIVE_NS,COMMAND_MISS_DISABLED,COMMAND_MISS_NO_COPY,COMMAND_MISS_SIZE,COMMAND_MISS_INVALID,COMMAND_MISS_MAPPING,COMMAND_MISS_UNKNOWN,COMMAND_MISS_CONTEXT,COMMAND_MISS_EVICTED,COMMAND_CACHE_BYTES,COMMAND_CACHE_PEAK_BYTES,COMMAND_READBACK_RETAINS,TEX_BUFFER_RANGE_CALLS,RANGE_ENTRY_NS,RANGE_STATE_NS,GUARD_ENTER_NS,GUARD_RESTORE_NS,RANGE_NATIVE_COPY_NS,RANGE_CPU_UPLOAD_NS,RANGE_CPU_STAGING_NS,RANGE_CPU_UPDATES,RANGE_GL_UPDATES,RANGE_CPU_AVAILABLE,RANGE_CPU_ABSENT,RANGE_GPU_UNKNOWN,RANGE_MAPPING,RANGE_UNTRUSTED,BATCH_SETUP_NS,INSTANCE_STATE_NS,DRAW_SUBMIT_NS,BATCH_FINISH_NS,BASE_CHANGES,LOGICAL_DRAWS,NATIVE_DRAWS,ROWS_SINGLE,ROWS_MULTI,INSTANCE_GROUP_BUILDS,INSTANCE_GROUP_HITS,POINTER_CACHE_HITS,ARRAY_BUFFER_SWITCHES,CONTEXT_FAST_HITS,CONTEXT_AUTHORITATIVE,GB_SURFACES_NS,GB_MODELS_NS,GB_FAR_BAND_NS,PICK_ENQUEUE_NS,PICK_POLL_NS,PICK_COLLECT_NS,PICK_READ_NS,INSTANCED_ATTRIBUTES,INSTANCED_BINDING_GROUPS,RANGE_GUARD_ENTER_NS,RANGE_GUARD_RESTORE_NS,RANGE_STAGING_ALLOCATIONS,RANGE_STAGING_BYTES,POINTER_STATE_ALLOCATIONS,PICK_PREPARE_NS,PICK_STATE_NS,PICK_READ_PIXELS_NS,PICK_FENCE_NS,PICK_RESTORE_NS,PICK_BUFFER_ALLOC_NS,PICK_BIND_CALLS,PICK_NATIVE_READS,PICK_FENCES,PICK_REQUESTS,PICK_RESULTS,PICK_READY,PICK_NOT_READY,PICK_AGE_FRAMES,PICK_LATENCY_NS,PICK_STAGED,PICK_ORIGINAL,PICK_COLLECT_BYTES_NS,METAL_ISLANDS,METAL_DRAWS,METAL_UNSUPPORTED,METAL_CPU_NS,METAL_GPU_NS,METAL_WAIT_NS,METAL_MERGE_NS,METAL_TRANSFER_BYTES,GLASS_SURFACES_NS,GLASS_MODELS_NS,GLASS_FLAMES_NS,GLASS_RESOLVE_NS,GLASS_TOTAL_NS,FAR_DRAW_NS,GL_SURFACE_SUBMIT_NS,GL_MODEL_SUBMIT_NS,GL_FAR_BAND_SUBMIT_NS,GL_GLASS_SURFACE_SUBMIT_NS,GL_GLASS_MODEL_SUBMIT_NS,GL_FLAME_SUBMIT_NS,GL_RESOLVE_SUBMIT_NS,GL_FAR_SUBMIT_NS,GL_SURFACE_DRAWS,GL_MODEL_DRAWS,GL_FAR_BAND_DRAWS,GL_GLASS_SURFACE_DRAWS,GL_GLASS_MODEL_DRAWS,GL_FLAME_DRAWS,GL_RESOLVE_DRAWS,GL_FAR_DRAWS,METAL_PATCH_BYTES,PICK_NATIVE_READ_PIXELS_NS,PICK_STAGE_PREPARE_NS,PICK_STAGE_DRAW_NS,PICK_STAGE_RESTORE_NS,PICK_FLUSH_NS,METAL_ENCODE_NS,METAL_GL_CONSUMER_WAIT_NS,METAL_RESIDENT_PEAK_BYTES,PICK_CALLS,PICK_RATE_SKIPS,PICK_AGE_CALLS,PACK_SETUP_NS,PACK_LAYOUT_NS,PACK_HEADER_NS,PACK_CAPACITY_NS,PACK_STAGE_NS,PACK_IMAGE_NS,PACK_RESTORE_NS,PACK_HEADER_BYTES,PACK_IMAGE_BYTES,PACK_TABLE_REUSES,PACK_TABLE_MISSES,PACK_TABLE_EVICTIONS}
    private static final Key[] KEYS=Key.values();
    private static final ThreadLocal<long[]> LOCAL=ThreadLocal.withInitial(()->new long[KEYS.length]);
    public static final boolean ENABLED=Options.TELEMETRY.equals("full");
    public static void add(Key key,long n){if(ENABLED)LOCAL.get()[key.ordinal()]+=n;}
    public static void set(Key key,long value){if(ENABLED)LOCAL.get()[key.ordinal()]=value;}
    public static void max(Key key,long value){if(ENABLED){long[] a=LOCAL.get();a[key.ordinal()]=Math.max(a[key.ordinal()],value);}}
    public static long value(Key key){return ENABLED?LOCAL.get()[key.ordinal()]:0;}
    public static long now(){return ENABLED?System.nanoTime():0;}
    public static void elapsed(Key key,long start){if(ENABLED)add(key,System.nanoTime()-start);}
    public static long[] snapshot(){return LOCAL.get().clone();}
    static long[] take(){long[] data=LOCAL.get(),copy=data.clone();java.util.Arrays.fill(data,0);return copy;}
    public static String columns(){StringBuilder s=new StringBuilder();for(Key k:KEYS)s.append(',').append(k.name().toLowerCase(java.util.Locale.ROOT));return s.toString();}
}
